insert into catalogo.destino(nombre, zona, estado) values ('Víctor Fajardo', 'Ayacucho', 'publicado') on conflict (nombre, zona) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0001-4000-8000-000000000001', d.id, 'cultural', 'Plaza Mayor de Huamanga', 'También la llaman Parque Sucre por el monumento al mariscal Antonio José de Sucre que está al centro. La rodean los portales Municipal, Constitución e Independencia, con arquerías de piedra en el primer nivel. Aquí se cruzan la vida universitaria, las procesiones de Semana Santa y las tardes de paseo.', -13.1588, -74.2238, 'publicado', 'https://www.bcrp.gob.pe/docs/Sucursales/Huancayo/Ayacucho-Atractivos.pdf', '2026-11-17', 'plaza-mayor-huamanga', 'Centro histórico de Ayacucho', 'El corazón de la ciudad: portales de piedra, casonas de los siglos XVI y XVII y la Catedral a un costado.', 'Está en pleno centro. Desde cualquier hospedaje del centro histórico se llega caminando.', array['Recorre los portales al atardecer, cuando se encienden las luces.','Desde aquí salen a pie las visitas a la Catedral y a la Iglesia de Santo Domingo, a una cuadra.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0001-4000-8000-000000000001', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plaza_de_Armas_-_Ayacucho.JPG?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Plaza_de_Armas_-_Ayacucho.JPG', 'Plaza Mayor de Ayacucho') on conflict (lugar_id, orden) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0001-4000-8000-000000000001', 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Portal_Municipal_Ayacucho.JPG?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Portal_Municipal_Ayacucho.JPG', 'Portal Municipal') on conflict (lugar_id, orden) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0001-4000-8000-000000000001', 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ciudad_de_Ayacucho.jpg?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Ciudad_de_Ayacucho.jpg', 'Vista de la ciudad de Ayacucho') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0002-4000-8000-000000000002', d.id, 'cultural', 'Catedral Basílica de Ayacucho', 'Construida en el siglo XVII, combina rasgos renacentistas y barrocos en un estilo mestizo. Fue declarada Patrimonio Cultural de la Nación en 1972. Es una de las iglesias que dan fama a Ayacucho como la ciudad de las 33 iglesias.', -13.1593, -74.2243, 'publicado', 'https://www.bcrp.gob.pe/docs/Sucursales/Huancayo/Ayacucho-Atractivos.pdf', '2026-11-17', 'catedral-de-ayacucho', 'Plaza Mayor, Ayacucho', 'Templo del siglo XVII que mezcla elementos renacentistas y barrocos, frente a la Plaza Mayor.', 'En el lado oriental de la Plaza Mayor.', array['Consulta los horarios de visita: el ingreso puede cerrarse durante las misas.','En Semana Santa es punto de partida de varias procesiones.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0002-4000-8000-000000000002', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Catedral_de_Ayacucho.jpg?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Catedral_de_Ayacucho.jpg', 'Fachada de la Catedral') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0003-4000-8000-000000000003', d.id, 'cultural', 'Arco del Triunfo', 'Monumento que recuerda la independencia del Perú, sellada en la Pampa de Ayacucho. Marca el inicio de una de las calles más caminadas del centro histórico.', -13.1612, -74.2245, 'publicado', 'https://es.wikipedia.org/wiki/Ayacucho', '2026-11-17', 'arco-del-triunfo', 'Jirón 28 de Julio, Ayacucho', 'Arco conmemorativo de la independencia, a pocas cuadras de la Plaza Mayor. Foto obligada del centro.', 'Camina unas cuadras al sur de la Plaza Mayor por el jirón 28 de Julio.', array['Combínalo con el recorrido por las iglesias del centro.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0003-4000-8000-000000000003', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ayacucho_arco2.jpg?width=1280', 'Qwertymith', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Ayacucho_arco2.jpg', 'Arco del Triunfo de Ayacucho') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0004-4000-8000-000000000004', d.id, 'arqueologico', 'Complejo Arqueológico Wari', 'Wari fue la capital de una civilización que dominó gran parte de la sierra y la costa entre los años 500 y 1000. El complejo se extiende entre los 2600 y 2900 m s. n. m. e incluye recintos, galerías y tumbas de piedra como las de Monqachayoq y Cheqo Wasi.', -13.06056, -74.19889, 'publicado', 'https://cdn.www.gob.pe/uploads/document/file/5534841/4924195-guia-del-viajero-ayacucho-espanol.pdf', '2026-11-17', 'complejo-arqueologico-wari', 'A 22 km al noreste de Huamanga', 'Lo que queda de la capital del imperio Wari, la primera gran organización expansiva de los Andes.', 'Los colectivos y combis hacia Quinua pasan por el complejo. Salen del centro de Huamanga; consulta tarifa y horario vigentes.', array['Lleva bloqueador y agua: el recorrido es al aire libre.','Puedes seguir el mismo día hacia Quinua y la Pampa de Ayacucho.']::text[], 2770 from catalogo.destino d where d.nombre='Quinua' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0004-4000-8000-000000000004', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tomb_at_Wari_ruins_near_Ayacucho.jpg?width=1280', 'Dominio público', 'CC0 1.0', 'https://commons.wikimedia.org/wiki/File:Tomb_at_Wari_ruins_near_Ayacucho.jpg', 'Tumba en el complejo Wari') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0005-4000-8000-000000000005', d.id, 'cultural', 'Santuario Histórico Pampa de Ayacucho', 'Aquí se libró el 9 de diciembre de 1824 la batalla que selló la independencia sudamericana. El santuario histórico existe desde 1980 y protege tanto el paisaje como su memoria. El obelisco, tallado en mármol blanco, mide más de 44 metros.', -13.04241, -74.13141, 'publicado', 'https://cdn.www.gob.pe/uploads/document/file/5534841/4924195-guia-del-viajero-ayacucho-espanol.pdf', '2026-11-17', 'santuario-pampa-de-ayacucho', 'Quinua, provincia de Huamanga', 'Escenario de la Batalla de Ayacucho de 1824. Un obelisco de 44 metros domina la pampa.', 'A unos 37 km de Huamanga. Se llega en colectivo hasta Quinua y desde el pueblo se sube a la pampa.', array['Cada 9 de diciembre se celebra el aniversario de la batalla.','Por la altura, el sol y el viento son fuertes: lleva abrigo ligero.']::text[], 3300 from catalogo.destino d where d.nombre='Quinua' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0005-4000-8000-000000000005', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obelisco_de_la_Pampa_de_la_Quinua.jpg?width=1280', 'Mythbuster', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Obelisco_de_la_Pampa_de_la_Quinua.jpg', 'Obelisco de la Pampa de Ayacucho') on conflict (lugar_id, orden) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0005-4000-8000-000000000005', 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obelisk_Battle_of_Ayacucho_and_Sucre_MC.jpg?width=1280', 'Christian Mehlführer', 'CC BY-SA', 'https://commons.wikimedia.org/wiki/File:Obelisk_Battle_of_Ayacucho_and_Sucre_MC.jpg', 'Estatua de Sucre y obelisco') on conflict (lugar_id, orden) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0005-4000-8000-000000000005', 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monument_to_the_Battle_of_Ayacucho_where_Peru_won_its_inependence_%287271029082%29.jpg?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Monument_to_the_Battle_of_Ayacucho_where_Peru_won_its_inependence_%287271029082%29.jpg', 'Monumento a la Batalla de Ayacucho') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0006-4000-8000-000000000006', d.id, 'cultural', 'Pueblo artesanal de Quinua', 'Quinua se presenta como la capital de la artesanía ayacuchana. En sus talleres puedes ver cómo se modela y pinta la cerámica tradicional. Está muy cerca de la Pampa de Ayacucho, así que se visitan juntas.', -13.05, -74.139, 'publicado', 'https://cdn.www.gob.pe/uploads/document/file/5534841/4924195-guia-del-viajero-ayacucho-espanol.pdf', '2026-11-17', 'pueblo-de-quinua', 'Quinua, a unos 37 km de Huamanga', 'Pueblo de ceramistas: las iglesitas de barro que coronan los techos ayacuchanos nacen aquí.', 'Colectivos desde el centro de Huamanga; el viaje toma alrededor de una hora.', array['Pregunta en los talleres si puedes ver el proceso de modelado.']::text[], 3300 from catalogo.destino d where d.nombre='Quinua' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0006-4000-8000-000000000006', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Quinua.JPG?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Quinua.JPG', 'Vista del pueblo de Quinua') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0007-4000-8000-000000000007', d.id, 'arqueologico', 'Vilcashuamán', 'Fue un importante centro administrativo inca. Destacan el ushnu, una pirámide ceremonial de cinco plataformas, y el Templo del Sol, sobre cuyas bases se construyó la iglesia colonial. A finales de julio se celebra el Vilcas Raymi.', -13.6533, -73.9536, 'publicado', 'https://cdn.www.gob.pe/uploads/document/file/5534841/4924195-guia-del-viajero-ayacucho-espanol.pdf', '2026-11-17', 'vilcashuaman', 'Provincia de Vilcashuamán', 'Centro inca con un ushnu de cinco plataformas y un Templo del Sol sobre el que se levantó una iglesia colonial.', 'Viaje por carretera desde Huamanga hacia el sur. Confirma salidas en los terminales autorizados.', array['Si coincides con el Vilcas Raymi (28 y 29 de julio), reserva hospedaje con tiempo.']::text[], 3470 from catalogo.destino d where d.nombre='Vilcashuamán' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0007-4000-8000-000000000007', 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vilcashuam%C3%A1n_-_Ayacucho_-_Per%C3%BA.jpg?width=1280', 'Ver autor en Wikimedia Commons', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Vilcashuam%C3%A1n_-_Ayacucho_-_Per%C3%BA.jpg', 'Vilcashuamán') on conflict (lugar_id, orden) do nothing;
insert into catalogo.foto_externa(lugar_id, orden, url, autor, licencia, fuente_url, descripcion) values ('c1a1e0de-0007-4000-8000-000000000007', 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Willkawaman_cathedral.jpg?width=1280', 'Ver autor en Wikimedia Commons', 'Licencia libre (ver página del archivo)', 'https://commons.wikimedia.org/wiki/File:Willkawaman_cathedral.jpg', 'Iglesia sobre el Templo del Sol') on conflict (lugar_id, orden) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0008-4000-8000-000000000008', d.id, 'natural', 'Aguas Turquesas de Millpu', 'Las pozas se formaron en el cauce del río Millpu, sobre roca caliza que tiñe el agua de turquesa. Se recorren por el borde del cañón en una caminata de 30 a 45 minutos. Bañarse daña el lugar: disfrútalo desde los miradores.', null, null, 'publicado', 'https://cdn.www.gob.pe/uploads/document/file/5534841/4924195-guia-del-viajero-ayacucho-espanol.pdf', '2026-11-17', 'aguas-turquesas-de-millpu', 'Circamarca, Huancaraylla', 'Una veintena de pozas turquesas escalonadas dentro de un cañón. Mejor época: mayo a noviembre.', 'Viaje de unas cuatro horas desde Huamanga hasta Circamarca y luego caminata corta. Muchos visitantes van con agencia.', array['Evita la temporada de lluvias (enero a marzo): el agua pierde su color.','Lleva calzado de trekking y sal temprano.']::text[], 3600 from catalogo.destino d where d.nombre='Víctor Fajardo' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-0009-4000-8000-000000000009', d.id, 'gastronomia', 'Picanterías de Huamanga', 'Las picanterías son locales familiares de comida criolla y andina, famosas por sus guisos picantes y sus sopas contundentes. Suelen abrir al mediodía y cerrar temprano, porque la cocina se prepara cada día. Pregunta por el plato del día y por la chicha de jora.', null, null, 'publicado', '', '2026-11-17', 'picanterias-de-huamanga', 'Centro y barrios tradicionales', 'Donde se prueba la cocina ayacuchana: puca picante, mondongo, patachi y chicharrón con mote.', 'Pregunta en tu hospedaje por las picanterías más cercanas y llega temprano al almuerzo.', array['Prueba el puca picante y el mondongo.','Lleva efectivo: no todos los locales aceptan tarjeta.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-000a-4000-8000-00000000000a', d.id, 'gastronomia', 'Mercados de Huamanga', 'Los mercados de la ciudad concentran puestos de desayuno, jugos, queso fresco, tamales y comida del día a precios populares. Es un buen lugar para conocer los productos de la zona.', null, null, 'publicado', '', '2026-11-17', 'mercado-central-huamanga', 'Centro de Huamanga', 'Desayunos con jugo y pan, frutas, quesos y tamales: la forma más barata y rápida de comer como local.', 'Están en el centro de la ciudad; se llega caminando desde la Plaza Mayor.', array['Ve temprano: lo mejor se acaba antes del mediodía.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.lugar(id, destino_id, tipo, nombre, descripcion, lat, lon, estado, fuente_url, revisado_en, slug, zona, resumen, como_llegar, recomendaciones, altitud_m) select 'c1a1e0de-000b-4000-8000-00000000000b', d.id, 'artesania', 'Barrio de artesanos de Santa Ana', 'Santa Ana es conocido por sus talleres de artesanos. Puedes ver retablos ayacuchanos, tejidos y trabajos en piedra de Huamanga, y conversar con quienes los elaboran.', null, null, 'publicado', '', '2026-11-17', 'barrio-de-artesanos-santa-ana', 'Barrio de Santa Ana', 'Talleres de retablos, tejidos y piedra de Huamanga, donde se ve cómo se hace cada pieza.', 'Está a pocas cuadras del centro; consulta la ruta en tu hospedaje.', array['Compra directo al artesano y pregunta el nombre de la técnica.']::text[], 2761 from catalogo.destino d where d.nombre='Huamanga' and d.zona='Ayacucho' on conflict (slug) do nothing;
insert into catalogo.terminal(id, nombre, datos) values ('terminal-libertadores', 'Terminal Terrestre Los Libertadores de América', '{"nombre": "Terminal Terrestre Los Libertadores de América", "tipo": "terminal", "referencia": "Av. Pérez de Cuéllar s/n (Asoc. Los Artesanos), Ayacucho", "lat": -13.134179, "lon": -74.230085, "mapa": "Terminal Terrestre Los Libertadores de América, Ayacucho", "horario": "", "frecuencia": "", "pasaje": "S/ 20 – 25", "descripcion": "Buses y colectivos a Vilcashuamán y a otras provincias.", "foto_url": "", "destinos": [{"slug": "vilcashuaman", "tiempo": "Entre 1 h 40 min y 2 h 30 min (unos 100 km)", "tarifa": "Entre S/ 20 y S/ 25 por persona, por tramo (bus o colectivo).", "nota": "En el pueblo, el mototaxi te acerca a los complejos arqueológicos. Las pistas pueden demorar el viaje."}], "fuentes": [{"nombre": "Marvelous Peru", "url": "https://www.marvelousperu.com/blog/vilcashuaman-templo-del-sol-y-la-luna/"}]}'::jsonb) on conflict (id) do nothing;
insert into catalogo.terminal(id, nombre, datos) values ('paradero-caceres', 'Paradero de colectivos en la Av. Mariscal Cáceres', '{"nombre": "Paradero de colectivos en la Av. Mariscal Cáceres", "tipo": "paradero", "referencia": "A la altura del Óvalo del Dios Wari, inicio de la carretera a Huanta", "lat": -13.158674, "lon": -74.218836, "mapa": "Óvalo del Dios Wari, Ayacucho", "horario": "Desde temprano", "frecuencia": "", "pasaje": "S/ 2 – 10", "descripcion": "Colectivos y combis hacia el Complejo Wari, Quinua y la Pampa de Ayacucho.", "foto_url": "", "destinos": [{"slug": "complejo-arqueologico-wari", "tiempo": "Entre 30 y 45 min", "tarifa": "Unos pocos soles por persona (una guía de viajeros lo ubica en S/ 2).", "nota": "Regresa temprano: pasada la tarde hay menos colectivos."}, {"slug": "pueblo-de-quinua", "tiempo": "Cerca de 1 hora", "tarifa": "Entre S/ 5 y S/ 10 por persona (combi o colectivo).", "nota": "Los colectivos salen desde temprano. Ya en Quinua, el mototaxi a los puntos del pueblo cuesta pocos soles."}, {"slug": "santuario-pampa-de-ayacucho", "tiempo": "Cerca de 1 hora hasta Quinua, más unos 10 min hasta la pampa", "tarifa": "Entre S/ 5 y S/ 10 por persona hasta Quinua; de ahí, unos S/ 5 a S/ 8 en taxi o mototaxi hasta la pampa.", "nota": "La vía Libertadores puede tener tramos en mal estado: pregunta por el estado de la pista antes de salir."}], "fuentes": [{"nombre": "El Comercio (Vamos)", "url": "https://elcomercio.pe/vamos/peru/ayacucho-10-atractivos-turisticos-que-no-puedes-dejar-de-conocer-fotos-noticia/"}, {"nombre": "Guía Sygic Travel", "url": "https://guides.travel.sygic.com/production/en/Ayacucho"}, {"nombre": "123 Perú", "url": "https://es.123peru.com/destinos/ayacucho/pampa-de-la-quinua-un-gigantesco-obelisco/"}, {"nombre": "Directorio de micros (2026)", "url": "https://www.directoriodemicros.com/2026/05/visitando-por-tu-cuenta-la-pampa-de-ayacucho.html"}]}'::jsonb) on conflict (id) do nothing;
insert into catalogo.terminal(id, nombre, datos) values ('paradero-cavero', 'Paradero de colectivos Jr. Salvador Cavero con Jr. Ciro Alegría', '{"nombre": "Paradero de colectivos Jr. Salvador Cavero con Jr. Ciro Alegría", "tipo": "paradero", "referencia": "Zona este de la ciudad (Urb. Santa Bertha)", "lat": -13.1572, "lon": -74.2159, "mapa": "Jr. Salvador Cavero con Jr. Ciro Alegría, Ayacucho", "horario": "Desde temprano", "frecuencia": "", "pasaje": "S/ 5 – 10", "descripcion": "Combis hacia Quinua y la Pampa de Ayacucho.", "foto_url": "", "destinos": [{"slug": "pueblo-de-quinua", "tiempo": "Cerca de 1 hora", "tarifa": "Entre S/ 5 y S/ 10 por persona (combi o colectivo).", "nota": "Los colectivos salen desde temprano. Ya en Quinua, el mototaxi a los puntos del pueblo cuesta pocos soles."}, {"slug": "santuario-pampa-de-ayacucho", "tiempo": "Cerca de 1 hora hasta Quinua, más unos 10 min hasta la pampa", "tarifa": "Entre S/ 5 y S/ 10 por persona hasta Quinua; de ahí, unos S/ 5 a S/ 8 en taxi o mototaxi hasta la pampa.", "nota": "La vía Libertadores puede tener tramos en mal estado: pregunta por el estado de la pista antes de salir."}], "fuentes": [{"nombre": "123 Perú", "url": "https://es.123peru.com/destinos/ayacucho/pampa-de-la-quinua-un-gigantesco-obelisco/"}, {"nombre": "Directorio de micros (2026)", "url": "https://www.directoriodemicros.com/2026/05/visitando-por-tu-cuenta-la-pampa-de-ayacucho.html"}]}'::jsonb) on conflict (id) do nothing;
